1	import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
2	import { execFileSync } from "node:child_process";
3	import { join, normalize, resolve } from "node:path";
4	import type { WorktreeInitResult, WorktreePullResult, WorktreeSyncResult } from "../types";
5	import { AgentrackError, ErrorCodes } from "./errors";
6	import type { WorktreeOptions } from "./branch-config";
7	
8	/** Default branch name used for the agentrack data worktree. */
9	export const DEFAULT_BRANCH = "_agentrack";
10	
11	/** Default directory name for the agentrack data worktree. */
12	export const DEFAULT_DIR = ".agentrack";
13	
14	/** @deprecated Use DEFAULT_BRANCH instead. */
15	export const WORKTREE_BRANCH = DEFAULT_BRANCH;
16	
17	/** @deprecated Use DEFAULT_DIR instead. */
18	export const WORKTREE_DIR = DEFAULT_DIR;
19	
20	/**
21	 * Default file contents for the orphan branch.
22	 * These match the Tracker.init() defaults exactly.
23	 */
24	const DEFAULT_CONFIG = { auth: { mode: "open", defaultUser: "anonymous" } };
25	const DEFAULT_INDEX = { open: [], closed: [], childrenOf: {} };
26	const DEFAULT_DEPENDENCIES = { blockedBy: {}, blocks: {} };
27	const DEFAULT_USERS = { users: [] };
28	
29	// ─── Git helpers ─────────────────────────────────────────────────────
30	
31	/**
32	 * Execute a git command synchronously using array-based argument passing.
33	 * Uses execFileSync to avoid shell injection.
34	 */
35	function gitExec(cwd: string, args: string[]): string {
36	  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
37	}
38	
39	/**
40	 * Extract stderr from an execFileSync error.
41	 */
42	function getGitError(err: unknown): string {
43	  if (typeof err === "object" && err !== null && "stderr" in err) {
44	    const stderr = (err as { stderr: unknown }).stderr;
45	    if (typeof stderr === "string") return stderr;
46	  }
47	  return (err as Error).message || String(err);
48	}
49	
50	/**
51	 * Check if `cwd` is inside a git repository.
52	 */
53	function isGitRepo(cwd: string): boolean {
54	  try {
55	    gitExec(cwd, ["rev-parse", "--git-dir"]);
56	    return true;
57	  } catch {
58	    return false;
59	  }
60	}
61	
62	/**
63	 * Get the current branch name.
64	 */
65	function getCurrentBranch(cwd: string): string {
66	  return gitExec(cwd, ["rev-parse", "--abbrev-ref", "HEAD"]).trim();
67	}
68	
69	/**
70	 * Check if a remote named 'origin' is configured.
71	 */
72	function hasRemote(cwd: string): boolean {
73	  try {
74	    const remotes = gitExec(cwd, ["remote"]);
75	    return remotes.split("\n").some((r) => r.trim() === "origin");
76	  } catch {
77	    return false;
78	  }
79	}
80	
81	/**
82	 * Create a blob object from content via stdin.
83	 * Returns the blob hash.
84	 */
85	function gitHashObject(cwd: string, content: string): string {
86	  // execFileSync supports Buffer input via input option
87	  return execFileSync("git", ["hash-object", "-w", "--stdin"], {
88	    cwd,
89	    encoding: "utf-8",
90	    input: content,
91	    stdio: ["pipe", "pipe", "pipe"],
92	  }).trim();
93	}
94	
95	/**
96	 * Create a tree object from formatted entries.
97	 */
98	function gitMkTree(cwd: string, entries: string): string {
99	  return execFileSync("git", ["mktree"], {
100	    cwd,
101	    encoding: "utf-8",
102	    input: entries,
103	    stdio: ["pipe", "pipe", "pipe"],
104	  }).trim();
105	}
106	
107	/**
108	 * Create a commit from a tree hash.
109	 */
110	function gitCommitTree(cwd: string, tree: string, message: string): string {
111	  return execFileSync("git", ["commit-tree", tree, "-m", message], {
112	    cwd,
113	    encoding: "utf-8",
114	    stdio: ["pipe", "pipe", "pipe"],
115	  }).trim();
116	}
117	
118	// ─── Gitignore helpers ───────────────────────────────────────────────
119	
120	/**
121	 * Check if the gitignore content already has an entry for the given directory.
122	 * Matches common patterns: /dir/, dir/, /dir, dir
123	 */
124	function gitignoreHasEntry(content: string, dir: string): boolean {
125	  return content.split("\n").some((rawLine) => {
126	    const line = rawLine.trim();
127	    // Skip comments and empty lines
128	    if (!line || line.startsWith("#")) return false;
129	    return (
130	      line === `/${dir}/` ||
131	      line === `${dir}/` ||
132	      line === `/${dir}` ||
133	      line === dir
134	    );
135	  });
136	}
137	
138	/**
139	 * Ensure .gitignore has an entry for the given directory.
140	 * Appends the entry if missing. Does NOT stage or commit.
141	 * Returns true if an entry was added.
142	 */
143	function ensureGitignoreEntry(cwd: string, dir: string): boolean {
144	  const gitignorePath = join(cwd, ".gitignore");
145	  if (existsSync(gitignorePath)) {
146	    const content = readFileSync(gitignorePath, "utf-8");
147	    if (gitignoreHasEntry(content, dir)) {
148	      return false;
149	    }
150	    // Append entry (ensure newline before if file doesn't end with one)
151	    const suffix = content.endsWith("\n") ? "" : "\n";
152	    writeFileSync(gitignorePath, `${content}${suffix}/${dir}/\n`, "utf-8");
153	  } else {
154	    writeFileSync(gitignorePath, `/${dir}/\n`, "utf-8");
155	  }
156	  return true;
157	}
158	
159	// ─── Precondition checks ─────────────────────────────────────────────
160	
161	/**
162	 * Validate preconditions before worktree initialization.
163	 * Throws AgentrackError if any precondition fails.
164	 */
165	function checkPreconditions(cwd: string, opts: WorktreeOptions): void {
166	  // Must be inside a git repo
167	  if (!isGitRepo(cwd)) {
168	    throw new AgentrackError(
169	      ErrorCodes.NOT_A_GIT_REPO.result,
170	      "Not inside a git repository",
171	      ErrorCodes.NOT_A_GIT_REPO.exitCode,
172	    );
173	  }
174	
175	  // Worktree dir must not exist as a non-worktree (legacy)
176	  const agentrackPath = join(cwd, opts.dir);
177	  if (existsSync(agentrackPath)) {
178	    const stat = statSync(agentrackPath);
179	    if (!stat.isDirectory()) {
180	      throw new AgentrackError(
181	        ErrorCodes.MIGRATION_REQUIRED.result,
182	        `${opts.dir} exists but is not a directory. Remove it and re-run init.`,
183	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
184	      );
185	    }
186	    // Directory exists — if not a worktree, it's a legacy directory
187	    if (!isWorktreeInitialized(cwd, opts)) {
188	      throw new AgentrackError(
189	        ErrorCodes.MIGRATION_REQUIRED.result,
190	        `${opts.dir}/ exists but is not a git worktree. Remove it manually and re-run init.`,
191	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
192	      );
193	    }
194	    // If it IS a valid worktree, caller should handle ALREADY_INITIALIZED
195	  }
196	
197	  // Must not be on the target branch
198	  const currentBranch = getCurrentBranch(cwd);
199	  if (currentBranch === opts.branch) {
200	    throw new AgentrackError(
201	      ErrorCodes.INVALID_STATE.result,
202	      `Cannot init: currently on the ${opts.branch} branch. Switch to a code branch first.`,
203	      ErrorCodes.INVALID_STATE.exitCode,
204	    );
205	  }
206	}
207	
208	// ─── Public API ──────────────────────────────────────────────────────
209	
210	/**
211	 * Detect which init scenario applies: 'fresh' (no remote branch) or 'join' (remote branch exists).
212	 */
213	export function detectInitScenario(cwd: string, opts?: WorktreeOptions): "fresh" | "join" {
214	  const { branch } = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
215	  try {
216	    const result = gitExec(cwd, ["ls-remote", "--heads", "origin", branch]);
217	    return result.trim().length > 0 ? "join" : "fresh";
218	  } catch {
219	    // No remote or no connectivity → fresh
220	    return "fresh";
221	  }
222	}
223	
224	/**
225	 * Check if the worktree directory is a valid git worktree for the target branch.
226	 * When opts is not provided, uses default branch/dir.
227	 */
228	export function isWorktreeInitialized(cwd: string, opts?: WorktreeOptions): boolean {
229	  const { dir } = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
230	  try {
231	    const worktreeList = gitExec(cwd, ["worktree", "list", "--porcelain"]);
232	    const normalizedCwd = resolve(cwd);
233	    const expectedPath = normalize(join(normalizedCwd, dir));
234	
235	    return worktreeList.split("\n").some((line) => {
236	      if (!line.startsWith("worktree ")) return false;
237	      const wtPath = line.slice("worktree ".length);
238	      return normalize(wtPath) === expectedPath;
239	    });
240	  } catch {
241	    return false;
242	  }
243	}
244	
245	/**
246	 * Scenario A: create orphan branch with initial data, push, mount worktree.
247	 * Uses git plumbing commands to avoid modifying the working tree.
248	 */
249	export function initFreshWorktree(cwd: string, opts?: WorktreeOptions): WorktreeInitResult {
250	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
251	  // 1. Create blob objects for initial files
252	  const configBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`);
253	  const indexBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_INDEX, null, 2)}\n`);
254	  const depsBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_DEPENDENCIES, null, 2)}\n`);
255	  const usersBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_USERS, null, 2)}\n`);
256	
257	  // 2. Create a tree object referencing these blobs
258	  const treeInput = [
259	    `100644 blob ${configBlob}\tconfig.json`,
260	    `100644 blob ${indexBlob}\tindex.json`,
261	    `100644 blob ${depsBlob}\tdependencies.json`,
262	    `100644 blob ${usersBlob}\tusers.json`,
263	  ].join("\n");
264	  const tree = gitMkTree(cwd, treeInput);
265	
266	  // 3. Create a commit from the tree
267	  const commit = gitCommitTree(cwd, tree, `init ${worktreeOpts.branch} branch`);
268	
269	  // 4. Create the branch ref
270	  try {
271	    gitExec(cwd, ["branch", worktreeOpts.branch, commit]);
272	  } catch (err) {
273	    // Branch might already exist from a failed previous attempt
274	    const stderr = getGitError(err);
275	    if (stderr.includes("already exists")) {
276	      // Force-update the branch to our new commit
277	      gitExec(cwd, ["branch", "-f", worktreeOpts.branch, commit]);
278	    } else {
279	      throw new AgentrackError(
280	        ErrorCodes.INVALID_STATE.result,
281	        `Failed to create branch: ${stderr}`,
282	        ErrorCodes.INVALID_STATE.exitCode,
283	      );
284	    }
285	  }
286	
287	  // 5. Push to remote (if available)
288	  if (hasRemote(cwd)) {
289	    try {
290	      gitExec(cwd, ["push", "-u", "origin", worktreeOpts.branch]);
291	    } catch (pushErr) {
292	      const stderr = getGitError(pushErr);
293	      // If push fails because branch already exists remotely, fall back to join
294	      if (
295	        stderr.includes("already exists") ||
296	        stderr.includes("failed to push") ||
297	        stderr.includes("non-fast-forward")
298	      ) {
299	        return initJoinWorktree(cwd, worktreeOpts);
300	      }
301	      // Network or other errors — proceed with local branch only (warn implicitly)
302	    }
303	  }
304	
305	  // 6. Ensure .gitignore entry
306	  ensureGitignoreEntry(cwd, worktreeOpts.dir);
307	
308	  // 7. Mount worktree
309	  try {
310	    gitExec(cwd, ["worktree", "add", worktreeOpts.dir, worktreeOpts.branch]);
311	  } catch (err) {
312	    const stderr = getGitError(err);
313	    throw new AgentrackError(
314	      ErrorCodes.INVALID_STATE.result,
315	      `Failed to mount worktree: ${stderr}`,
316	      ErrorCodes.INVALID_STATE.exitCode,
317	    );
318	  }
319	
320	  return { scenario: "fresh", path: resolve(cwd, worktreeOpts.dir) };
321	}
322	
323	/**
324	 * Scenario B: fetch remote branch, create tracking branch, mount worktree.
325	 */
326	export function initJoinWorktree(cwd: string, opts?: WorktreeOptions): WorktreeInitResult {
327	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
328	  // 1. Fetch the remote branch
329	  try {
330	    gitExec(cwd, ["fetch", "origin", worktreeOpts.branch]);
331	  } catch (err) {
332	    const stderr = getGitError(err);
333	    throw new AgentrackError(
334	      ErrorCodes.INVALID_STATE.result,
335	      `Failed to fetch remote branch: ${stderr}`,
336	      ErrorCodes.INVALID_STATE.exitCode,
337	    );
338	  }
339	
340	  // 2. Create local tracking branch
341	  try {
342	    gitExec(cwd, ["branch", worktreeOpts.branch, `origin/${worktreeOpts.branch}`]);
343	  } catch {
344	    // Branch might already exist — force-update to remote ref
345	    try {
346	      gitExec(cwd, ["branch", "-f", worktreeOpts.branch, `origin/${worktreeOpts.branch}`]);
347	    } catch (err) {
348	      const stderr = getGitError(err);
349	      throw new AgentrackError(
350	        ErrorCodes.INVALID_STATE.result,
351	        `Failed to create tracking branch: ${stderr}`,
352	        ErrorCodes.INVALID_STATE.exitCode,
353	      );
354	    }
355	  }
356	
357	  // 3. Ensure .gitignore entry
358	  ensureGitignoreEntry(cwd, worktreeOpts.dir);
359	
360	  // 4. Mount worktree
361	  try {
362	    gitExec(cwd, ["worktree", "add", worktreeOpts.dir, worktreeOpts.branch]);
363	  } catch (err) {
364	    const stderr = getGitError(err);
365	    throw new AgentrackError(
366	      ErrorCodes.INVALID_STATE.result,
367	      `Failed to mount worktree: ${stderr}`,
368	      ErrorCodes.INVALID_STATE.exitCode,
369	    );
370	  }
371	
372	  return { scenario: "join", path: resolve(cwd, worktreeOpts.dir) };
373	}
374	
375	/**
376	 * Initialize the agentrack worktree. Performs precondition checks, detects the
377	 * scenario, and delegates to the appropriate setup function.
378	 *
379	 * Returns the init result, or throws AgentrackError on failure.
380	 *
381	 * When opts is not provided, uses default branch/dir.
382	 */
383	export function initWorktree(cwd: string, opts?: WorktreeOptions): WorktreeInitResult {
384	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
385	
386	  // Check if already initialized
387	  if (isWorktreeInitialized(cwd, worktreeOpts)) {
388	    return { scenario: "already_initialized", path: resolve(cwd, worktreeOpts.dir) };
389	  }
390	
391	  // Validate preconditions (throws on failure)
392	  checkPreconditions(cwd, worktreeOpts);
393	
394	  // Detect scenario and delegate
395	  const scenario = detectInitScenario(cwd, worktreeOpts);
396	  if (scenario === "fresh") {
397	    return initFreshWorktree(cwd, worktreeOpts);
398	  }
399	  return initJoinWorktree(cwd, worktreeOpts);
400	}
401	
402	/**
403	 * Stage and commit .gitignore changes (and pointer file if present) on the current code branch.
404	 * Used after initWorktree() to persist the worktree dir gitignore entry and pointer file.
405	 * No-op if there are no changes to commit.
406	 */
407	export function commitGitignoreChange(cwd: string, dir?: string): void {
408	  const entry = dir ?? DEFAULT_DIR;
409	  try {
410	    gitExec(cwd, ["add", ".gitignore"]);
411	    // Also stage pointer file if it exists
412	    if (existsSync(join(cwd, ".agentrack.json"))) {
413	      gitExec(cwd, ["add", ".agentrack.json"]);
414	    }
415	    gitExec(cwd, ["commit", "-m", `chore: add ${entry}/ to .gitignore`]);
416	  } catch {
417	    // No changes to commit or .gitignore unchanged
418	  }
419	}
420	
421	/**
422	 * Stage all changes in the worktree and commit them with the given message.
423	 * Used after tracker.init() to persist initial data to the worktree branch.
424	 */
425	export function commitWorktreeData(cwd: string, message: string, opts?: WorktreeOptions): void {
426	  const dir = opts?.dir ?? DEFAULT_DIR;
427	  const worktreeDir = join(cwd, dir);
428	  gitExec(worktreeDir, ["add", "-A"]);
429	  try {
430	    gitExec(worktreeDir, ["commit", "-m", message]);
431	  } catch {
432	    // No changes to commit — that's fine (e.g., data already committed)
433	  }
434	}
435	
436	/**
437	 * Stage all changes, auto-commit, and push to remote.
438	 *
439	 * When opts is not provided, resolves branch from pointer file or defaults.
440	 */
441	export function pushWorktree(cwd: string, message?: string, opts?: WorktreeOptions): WorktreeSyncResult {
442	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
443	  const worktreeDir = join(cwd, worktreeOpts.dir);
444	
445	  // Verify worktree is initialized
446	  if (!isWorktreeInitialized(cwd, worktreeOpts)) {
447	    throw new AgentrackError(
448	      ErrorCodes.NOT_INITIALIZED.result,
449	      "Agentrack not initialized. Run `agt init` first.",
450	      ErrorCodes.NOT_INITIALIZED.exitCode,
451	    );
452	  }
453	
454	  // Stage all changes
455	  gitExec(worktreeDir, ["add", "-A"]);
456	
457	  // Check for staged changes
458	  let hasStagedChanges = false;
459	  try {
460	    gitExec(worktreeDir, ["diff", "--cached", "--quiet"]);
461	    // Exit code 0 = no diff = no staged changes
462	  } catch {
463	    // Exit code 1 = there are staged changes
464	    hasStagedChanges = true;
465	  }
466	
467	  if (hasStagedChanges) {
468	    // Commit staged changes
469	    const commitMessage =
470	      message || `sync: ${new Date().toISOString()}`;
471	    try {
472	      gitExec(worktreeDir, ["commit", "-m", commitMessage]);
473	    } catch (err) {
474	      const stderr = getGitError(err);
475	      throw new AgentrackError(
476	        ErrorCodes.PUSH_FAILED.result,
477	        `git commit failed: ${stderr}`,
478	        ErrorCodes.PUSH_FAILED.exitCode,
479	      );
480	    }
481	  }
482	
483	  // Check if there's anything to push
484	  let hasUnpushedCommits = false;
485	  try {
486	    const count = gitExec(worktreeDir, ["rev-list", "--count", "@{upstream}..HEAD"]).trim();
487	    hasUnpushedCommits = parseInt(count, 10) > 0;
488	  } catch {
489	    // No upstream set — means we need to push
490	    hasUnpushedCommits = true;
491	  }
492	
493	  if (!hasStagedChanges && !hasUnpushedCommits) {
494	    return { synced: false, message: "No changes to sync" };
495	  }
496	
497	  // Push to remote
498	  if (hasRemote(cwd)) {
499	    try {
500	      gitExec(worktreeDir, ["push"]);
501	    } catch (err) {
502	      const stderr = getGitError(err);
503	      throw new AgentrackError(
504	        ErrorCodes.PUSH_FAILED.result,
505	        `git push failed: ${stderr}`,
506	        ErrorCodes.PUSH_FAILED.exitCode,
507	      );
508	    }
509	  }
510	
511	  return {
512	    synced: true,
513	    commitCount: hasStagedChanges ? 1 : 0,
514	  };
515	}
516	
517	/**
518	 * Pull latest from remote into the worktree.
519	 *
520	 * When opts is not provided, resolves branch from pointer file or defaults.
521	 */
522	export function pullWorktree(cwd: string, opts?: WorktreeOptions): WorktreePullResult {
523	  const worktreeOpts = opts ?? { branch: DEFAULT_BRANCH, dir: DEFAULT_DIR };
524	  const worktreeDir = join(cwd, worktreeOpts.dir);
525	
526	  // Verify worktree is initialized
527	  if (!isWorktreeInitialized(cwd, worktreeOpts)) {
528	    throw new AgentrackError(
529	      ErrorCodes.NOT_INITIALIZED.result,
530	      "Agentrack not initialized. Run `agt init` first.",
531	      ErrorCodes.NOT_INITIALIZED.exitCode,
532	    );
533	  }
534	
535	  try {
536	    const output = gitExec(worktreeDir, ["pull"]);
537	    // "Already up to date." means no updates
538	    const updated = !output.includes("Already up to date");
539	    return { updated };
540	  } catch (err) {
541	    const stderr = getGitError(err);
542	    throw new AgentrackError(
543	      ErrorCodes.PULL_FAILED.result,
544	      `git pull failed: ${stderr}`,
545	      ErrorCodes.PULL_FAILED.exitCode,
546	    );
547	  }
548	}
