165	/**
166	 * Tracker — the main programmatic API for agentrack.
167	 *
168	 * Provides methods for issue CRUD, comments, blockages, user management,
169	 * and event history. The constructor accepts a `cwd` parameter that defaults
170	 * to `process.cwd()`. It does NOT validate that `.agentrack/` exists at
171	 * construction time — resolution happens on each method call.
172	 *
173	 * @example
174	 * ```typescript
175	 * import { Tracker } from "agentrack";
176	 *
177	 * const tracker = new Tracker("/path/to/project");
178	 * await tracker.init();
179	 * const { id } = await tracker.create({ title: "My first issue" });
180	 * ```
181	 */
182	export class Tracker {
183	  private cwd: string;
184	
185	  /**
186	   * Create a new Tracker instance.
187	   *
188	   * @param cwd - Working directory to resolve `.agentrack/` from. Defaults to `process.cwd()`.
189	   */
190	  constructor(cwd?: string) {
191	    this.cwd = cwd ?? process.cwd();
192	  }
193	
194	  /**
195	   * Initialize a new agentrack data directory in `cwd`.
196	   *
197	   * Creates the directory structure with all initial files:
198	   * `config.json`, `index.json`, `dependencies.json`, `users.json`,
199	   * and an empty `issues/` subdirectory.
200	   *
201	   * When `dirName` is not provided, resolves the directory from the pointer
202	   * file (`.agentrack.json`) or falls back to `.agentrack/`.
203	   *
204	   * @param dirName - Optional directory name override (e.g. ".testing")
205	   * @returns `{ result: "OK", path }` on success, or `{ result: "ALREADY_INITIALIZED", path }` if already exists
206	   *
207	   * @example
208	   * ```typescript
209	   * const result = await tracker.init();
210	   * if (result.result === "OK") console.log("Created at", result.path);
211	   * ```
212	   */
213	  async init(dirName?: string): Promise<InitResult> {
214	    const dir = dirName ?? resolveWorktreeOptions(this.cwd).dir;
215	    const trackerDir = join(this.cwd, dir);
216	
217	    if (existsSync(trackerDir)) {
218	      return { result: "ALREADY_INITIALIZED", path: resolve(trackerDir) };
219	    }
220	
221	    mkdirSync(trackerDir, { recursive: true });
222	    mkdirSync(join(trackerDir, "issues"), { recursive: true });
223	
224	    await atomicWriteJSON(join(trackerDir, "config.json"), DEFAULT_CONFIG);
225	    await atomicWriteJSON(join(trackerDir, "index.json"), DEFAULT_INDEX);
226	    await atomicWriteJSON(join(trackerDir, "dependencies.json"), DEFAULT_DEPENDENCIES);
227	    await atomicWriteJSON(join(trackerDir, "users.json"), DEFAULT_USERS);
228	
229	    return { result: "OK", path: resolve(trackerDir) };
230	  }
