232	  /**
233	   * Create a new issue.
234	   *
235	   * Generates a unique ID, creates the issue file with creation + update events,
236	   * and inserts an entry into the sorted index. Validates parent constraints if
237	   * `parentId` is provided.
238	   *
239	   * @param params - Creation parameters
240	   * @param params.title - The issue title (required)
241	   * @param params.description - Optional description, defaults to ""
242	   * @param params.status - Initial status, defaults to "idea"
243	   * @param params.priority - Priority 1-5, defaults to 3
244	   * @param params.assignee - Optional assignee, defaults to null
245	   * @param params.tags - Optional tags, defaults to []
246	   * @param params.parentId - Optional parent issue ID for hierarchy
247	   * @param params.author - Override author (resolved by auth layer if not provided)
248	   * @returns `{ id }` on success, or a AgentrackError on auth failure
249	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
250	   * @throws {AgentrackError} NOT_FOUND if parentId doesn't exist in index
251	   * @throws {AgentrackError} HIERARCHY_CONSTRAINT if parent is closed
252	   *
253	   * @example
254	   * ```typescript
255	   * const { id } = await tracker.create({
256	   *   title: "Bug fix",
257	   *   priority: 1,
258	   *   tags: ["bug", "urgent"],
259	   * });
260	   * ```
261	   */
262	  async create(params: CreateParams): Promise<CreateResult> {
263	    const trackerDir = resolveTrackerDir(this.cwd);
264	    if (!trackerDir) {
265	      throw new AgentrackError(
266	        ErrorCodes.NOT_INITIALIZED.result,
267	        "No .agentrack/ directory found. Run `agt init` first.",
268	        ErrorCodes.NOT_INITIALIZED.exitCode,
269	      );
270	    }
271	
272	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
273	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
274	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
275	    if (authResult instanceof AgentrackError) return authResult;
276	    const author = params.author ?? authResult.author;
277	
278	    const id = generateId();
279	    const issuePath = params.path ?? `issues/${id}.json`;
280	    const now = new Date().toISOString();
281	
282	    const title = params.title;
283	    const description = params.description ?? "";
284	    const status: IssueStatus = params.status ?? "idea";
285	    const priority = params.priority ?? 3;
286	    const assignee = params.assignee ?? null;
287	    const parentId = params.parentId ?? null;
288	    const tags = params.tags ?? [];
289	
290	    // Read index early for parent validation
291	    const index = await readIndex(trackerDir);
292	
293	    // Validate parent exists and is not closed
294	    if (parentId) {
295	      const parentEntry = findEntry(index, parentId);
296	      if (!parentEntry) {
297	        throw new AgentrackError(
298	          ErrorCodes.NOT_FOUND.result,
299	          `Parent issue \`${parentId}\` not found in index.`,
300	          ErrorCodes.NOT_FOUND.exitCode,
301	        );
302	      }
303	      const validationError = validateNewChild(parentEntry);
304	      if (validationError) {
305	        throw new AgentrackError(
306	          ErrorCodes.HIERARCHY_CONSTRAINT.result,
307	          validationError,
308	          ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
309	        );
310	      }
311	    }
312	
313	    // Build update content with only non-default values
314	    const updateContent: Partial<
315	      Pick<
316	        IssueProperties,
317	        "title" | "description" | "status" | "assignee" | "tags" | "priority" | "parentId"
318	      >
319	    > & { title: string } = { title };
320	    if (description) updateContent.description = description;
321	    if (status !== "idea") updateContent.status = status;
322	    if (priority !== 3) updateContent.priority = priority;
323	    if (assignee !== null) updateContent.assignee = assignee;
324	    if (parentId !== null) updateContent.parentId = parentId;
325	    if (tags.length > 0) updateContent.tags = tags;
326	
327	    // Create issue file with two events: creation + update
328	    const creationEvent = { type: "creation" as const, timestamp: now, author };
329	    const updateEvent = {
330	      type: "update" as const,
331	      timestamp: now,
332	      author,
333	      content: updateContent,
334	    };
335	
336	    const issueFilePath = join(trackerDir, issuePath);
337	    await atomicWriteJSON(issueFilePath, [creationEvent, updateEvent]);
338	
339	    // Build index entry and insert into index
340	    const entry: IndexEntry = {
341	      id,
342	      title,
343	      path: issuePath,
344	      status,
345	      assignee,
346	      parentId,
347	      tags,
348	      priority,
349	    };
350	
351	    const updatedIndex = insertEntry(index, entry);
352	    await writeIndex(trackerDir, updatedIndex);
353	
354	    return { id };
355	  }
