357	  /**
358	   * List issues from the index with optional filters.
359	   *
360	   * Returns entries sorted by: priority ASC → impact score DESC → id ASC.
361	   * Impact score is the count of active issues this issue blocks.
362	   *
363	   * @param params - Optional filter parameters
364	   * @param params.status - Filter by status; "open" = all non-closed, "closed" = closed only
365	   * @param params.assignee - Filter by assignee name
366	   * @param params.tags - AND filter — issue must have ALL specified tags
367	   * @param params.parentId - Filter by parent ID; null = top-level issues only
368	   * @returns Array of index entries matching the filters
369	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
370	   * @throws {AgentrackError} TOKEN_REQUIRED if auth mode is strict and no token provided
371	   *
372	   * @example
373	   * ```typescript
374	   * const openUrgent = await tracker.list({
375	   *   status: "open",
376	   *   tags: ["urgent"],
377	   *   parentId: null,
378	   * });
379	   * ```
380	   */
381	  async list(params?: ListParams): Promise<ListResult> {
382	    const trackerDir = resolveTrackerDir(this.cwd);
383	    if (!trackerDir) {
384	      throw new AgentrackError(
385	        ErrorCodes.NOT_INITIALIZED.result,
386	        "No .agentrack/ directory found. Run `agt init` first.",
387	        ErrorCodes.NOT_INITIALIZED.exitCode,
388	      );
389	    }
390	
391	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
392	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
393	    const authResult = resolveAuthor({ config, users, requiresWrite: false });
394	    if (authResult instanceof AgentrackError) {
395	      throw authResult;
396	    }
397	
398	    const index = await readIndex(trackerDir);
399	
400	    // Determine source arrays based on params.status
401	    let entries: IndexEntry[];
402	    if (params?.status === "closed") {
403	      entries = index.closed;
404	    } else if (params?.status === "open") {
405	      entries = index.open;
406	    } else if (params?.status) {
407	      entries = index.open;
408	    } else {
409	      entries = [...index.open, ...index.closed];
410	    }
411	
412	    // Filter in memory
413	    let filtered = entries;
414	
415	    if (params?.status && params.status !== "open" && params.status !== "closed") {
416	      filtered = filtered.filter((e) => e.status === params.status);
417	    }
418	
419	    if (params?.assignee) {
420	      filtered = filtered.filter((e) => e.assignee === params.assignee);
421	    }
422	
423	    if (params?.tags && params.tags.length > 0) {
424	      filtered = filtered.filter((e) => params.tags?.every((tag) => e.tags.includes(tag)));
425	    }
426	
427	    if (params?.parentId !== undefined) {
428	      if (params.parentId === null) {
429	        filtered = filtered.filter((e) => e.parentId === null);
430	      } else {
431	        filtered = filtered.filter((e) => e.parentId === params.parentId);
432	      }
433	    }
434	
435	    // Read dependencies once for impact score
436	    let deps: DependenciesFile | null = null;
437	
438	    // Sort: priority ASC → impact DESC → id ASC
439	    filtered.sort((a, b) => {
440	      if (a.priority !== b.priority) return a.priority - b.priority;
441	      // Lazy-load deps only once for sorting
442	      if (!deps) {
443	        deps = readDependenciesSync(trackerDir);
444	      }
445	      const impactA = getImpactScore(deps, a.id);
446	      const impactB = getImpactScore(deps, b.id);
447	      if (impactA !== impactB) return impactB - impactA;
448	      return a.id.localeCompare(b.id);
449	    });
450	
451	    return filtered;
452	  }
