512	  /**
513	   * Get the recommended next issue to work on for a given user.
514	   *
515	   * Filters open issues by assignee and active status, excludes blocked issues,
516	   * then sorts by priority ASC → impact DESC → id ASC and returns the top issue.
517	   *
518	   * @param assignee - The assignee name to filter by (case-sensitive)
519	   * @returns The recommended ComputedIssue, or `{ result: "NO_ISSUES_AVAILABLE" }`
520	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
521	   * @throws {AgentrackError} TOKEN_REQUIRED if auth mode is strict and no token provided
522	   *
523	   * @example
524	   * ```typescript
525	   * const result = await tracker.next("alice");
526	   * if ("title" in result) console.log("Work on:", result.title);
527	   * else console.log("No issues available:", result.message);
528	   * ```
529	   */
530	  async next(assignee: string): Promise<NextResult> {
531	    const trackerDir = resolveTrackerDir(this.cwd);
532	    if (!trackerDir) {
533	      throw new AgentrackError(
534	        ErrorCodes.NOT_INITIALIZED.result,
535	        "No .agentrack/ directory found. Run `agt init` first.",
536	        ErrorCodes.NOT_INITIALIZED.exitCode,
537	      );
538	    }
539	
540	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
541	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
542	    const authResult = resolveAuthor({ config, users, requiresWrite: false });
543	    if (authResult instanceof AgentrackError) {
544	      throw authResult;
545	    }
546	
547	    const index = await readIndex(trackerDir);
548	
549	    // Filter to open issues assigned to this user that are todo (ready to start)
550	    let candidates = index.open.filter(
551	      (e) => e.assignee === assignee && e.status === "todo",
552	    );
553	
554	    // Read dependencies for blockage filtering and impact scoring
555	    const deps = readDependenciesSync(trackerDir);
556	
557	    // Filter out issues with any active blockages
558	    candidates = candidates.filter((e) => {
559	      const blockedBy = deps.blockedBy[e.id] ?? [];
560	      return !blockedBy.some((b) => b.status === "active");
561	    });
562	
563	    // If no candidates remain, return no issues available
564	    if (candidates.length === 0) {
565	      return {
566	        result: "NO_ISSUES_AVAILABLE",
567	        message: `No todo issues found for user '${assignee}'.`,
568	      };
569	    }
570	
571	    // Sort: priority ASC → impact DESC → id ASC
572	    candidates.sort((a, b) => {
573	      if (a.priority !== b.priority) return a.priority - b.priority;
574	      const impactA = getImpactScore(deps, a.id);
575	      const impactB = getImpactScore(deps, b.id);
576	      if (impactA !== impactB) return impactB - impactA;
577	      return a.id.localeCompare(b.id);
578	    });
579	
580	    // Take top issue, replay events, return computed state
581	    const topEntry = candidates[0]!;
582	    const issueFilePath = join(trackerDir, topEntry.path);
583	    if (!existsSync(issueFilePath)) {
584	      throw new AgentrackError(
585	        ErrorCodes.ISSUE_MISSING.result,
586	        `Issue file for \`${topEntry.id}\` is missing.`,
587	        ErrorCodes.ISSUE_MISSING.exitCode,
588	      );
589	    }
590	
591	    const events = await replayEvents(issueFilePath);
592	    return computeState(events, topEntry.id);
593	  }
