767	    // ── Hierarchy handling (after event append, before index write) ─
768	
769	    // 1. Handle reparenting (childrenOf updates)
770	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
771	      // Detach from old parent
772	      if (oldParentId !== null) {
773	        updatedIndex = removeChild(updatedIndex, oldParentId, id);
774	      }
775	      // Attach to new parent
776	      if (params.parentId !== null) {
777	        updatedIndex = addChild(updatedIndex, params.parentId, id);
778	
779	        // Upward promotion for reparenting: if child's status is past new parent's status
780	        const newParentEntry = findEntry(updatedIndex, params.parentId);
781	        if (newParentEntry && isStatusAfter(computed.status, newParentEntry.status)) {
782	          const promotions = computeUpwardPromotions(
783	            updatedIndex,
784	            newParentEntry,
785	            computed.status,
786	            (iid) => findEntry(updatedIndex, iid),
787	          );
788	          for (const promo of promotions) {
789	            const promoEntry = findEntry(updatedIndex, promo.issueId);
790	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
791	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
792	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
793	                status: promo.event.content.status,
794	              });
795	            }
796	          }
797	        }
798	      }
799	    }
800	
801	    // 2. Handle status change
802	    if (params.status !== undefined && params.status !== oldStatus) {
803	      // Downward cascade: auto-close done children when parent closes
804	      if (params.status === "closed") {
805	        updatedIndex = await cascadeClose(updatedIndex, id, trackerDir);
806	      }
807	
808	      // Upward promotion: promote parent if child advanced past it
809	      const currentParentId = computed.parentId;
810	      if (currentParentId) {
811	        const parentEntry = findEntry(updatedIndex, currentParentId);
812	        if (parentEntry && isStatusAfter(params.status, parentEntry.status)) {
813	          const promotions = computeUpwardPromotions(
814	            updatedIndex,
815	            parentEntry,
816	            params.status,
817	            (iid) => findEntry(updatedIndex, iid),
818	          );
819	          for (const promo of promotions) {
820	            const promoEntry = findEntry(updatedIndex, promo.issueId);
821	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
822	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
823	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
824	                status: promo.event.content.status,
825	              });
826	            }
827	          }
828	        }
829	      }
830	    }
831	
832	    await writeIndex(trackerDir, updatedIndex);
833	
834	    // ── Auto-resolution: resolve active blockages when issue → done/closed ──
835	    if (params.status !== undefined && params.status !== oldStatus) {
836	      if (params.status === "done" || params.status === "closed") {
837	        const deps = await readDependencies(trackerDir);
838	        const activeBlocks = (deps.blocks[id] ?? []).filter((e) => e.status === "active");
