    const issueFilePath = join(trackerDir, blockedEntry.path);

    for (const blockerId of params.blockerIds) {
      const now = new Date().toISOString();
      const event: Event = {
        type: "blockage-deleted",
        timestamp: now,
        author,
        content: { blockerId },
      };
      await appendEvent(issueFilePath, event);
    }

    return { result: "OK" };
